from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class ExternalInterface(SchemaObject):
    name = SchemaField(name='name', not_null=True)
    ipv4_address = SchemaField(name='ipv4Address')
    ipv6_address = SchemaField(name='ipv6Address')
    fqdn = SchemaField(name='fqdn', optional=True)

    def __init__(self, name, ipv4_address, ipv6_address, fqdn):
        self.name = name
        self.ipv4_address = ipv4_address
        self.ipv6_address = ipv6_address
        self.fqdn = fqdn

        super(ExternalInterface, self).__init__()
